// Example 1: Basic module resolution in contract initialization
contract LiquidityManager {
    IBeacon public immutable beacon;
    ITokenManager public tokenManager;

    constructor(address _beaconAddress) {
        beacon = IBeacon(_beaconAddress);
        address tmAddress = beacon.getImplementation("TokenManager");
        tokenManager = ITokenManager(tmAddress);
    }
}

// Example 2: Dynamic resolution with interface casting
IBeacon beacon = IBeacon(0x123...);
address proxyAddr = beacon.getImplementation("ProxyGeneral");
IProxyGeneral proxy = IProxyGeneral(proxyAddr);
uint256 balance = proxy.balanceOf(msg.sender);

// Example 3: Multiple module lookups
function initializeModules(address _beacon) internal {
    IBeacon b = IBeacon(_beacon);
    tokenManager = ITokenManager(b.getImplementation("TokenManager"));
    valueCalculator = IValueCalculator(b.getImplementation("ValueCalculator"));
    swapManager = ISwapManager(b.getImplementation("SwapManager"));
}

// Example 4: Error handling with try-catch
try beacon.getImplementation("OptionalModule") returns (address impl) {
    optionalModule = IOptionalModule(impl);
} catch {
    // Module not available, use fallback behavior
    emit ModuleNotAvailable("OptionalModule");
}

