// Example 1: Standard module upgrade workflow
// Step 1: Deploy new implementation contract
LiquidityManagerV2 newLM = new LiquidityManagerV2(beaconAddress);

// Step 2: Verify deployment was successful
require(address(newLM) != address(0), "Deployment failed");

// Step 3: Update Beacon registry (only owner can call)
IBeacon beacon = IBeacon(beaconAddress);
beacon.updateImplementation("LiquidityManager", address(newLM));

// Step 4: Verify update
address currentImpl = beacon.getImplementation("LiquidityManager");
assert(currentImpl == address(newLM));

// Example 2: Batch upgrade with validation
contract UpgradeManager {
    IBeacon public beacon;

    function performUpgrade(
        string memory moduleName,
        address newImplementation
    ) external onlyRole(UPGRADER_ROLE) {
        // Pre-upgrade checks
        require(beacon.checkModuleExists(moduleName), "Module not registered");
        address oldImpl = beacon.getImplementation(moduleName);

        // Store old implementation for potential rollback
        previousImplementations[moduleName] = oldImpl;

        // Perform upgrade
        beacon.updateImplementation(moduleName, newImplementation);

        // Post-upgrade verification
        address updatedImpl = beacon.getImplementation(moduleName);
        require(updatedImpl == newImplementation, "Upgrade verification failed");

        emit ModuleUpgraded(moduleName, oldImpl, newImplementation);
    }
}

// Example 3: First-time module registration
// Deploy a new plugin or adapter
UniswapV4Plugin uniV4 = new UniswapV4Plugin(beaconAddress);

// Register it as a new module
beacon.updateImplementation("UniswapV4Plugin", address(uniV4));
// Note: This also adds to registeredModules array and sets moduleExists to true

// Example 4: Emergency upgrade (after unfreezing)
// If a module has a critical bug and was frozen:
// 1. Deploy patched version
TokenManagerV2_Patched patched = new TokenManagerV2_Patched(beaconAddress);

// 2. Unfreeze module (owner only)
beacon.unfreezeModule("TokenManager");

// 3. Immediately upgrade
beacon.updateImplementation("TokenManager", address(patched));

// 4. Re-freeze if still investigating
