// Example 2: Protocol health check - verify all expected modules exist
contract ProtocolHealthChecker {
    IBeacon public beacon;
    string[] public expectedModules = [
        "ProxyGeneral",
        "TokenManager",
        "ValueCalculator",
        "LiquidityManager",
        "SwapManager",
        "EmergencyHandler",
        "ParameterManager"
    ];

    function checkAllModulesRegistered() external view returns (bool allPresent, string[] memory missing) {
        string[] memory registered = beacon.getRegisteredModules();

        // Create temporary array for missing modules
        string[] memory tempMissing = new string[](expectedModules.length);
        uint256 missingCount = 0;

        for (uint256 i = 0; i < expectedModules.length; i++) {
            bool found = false;
            for (uint256 j = 0; j < registered.length; j++) {
                if (keccak256(bytes(expectedModules[i])) == keccak256(bytes(registered[j]))) {
                    found = true;
                    break;
                }
            }
            if (!found) {
                tempMissing[missingCount] = expectedModules[i];
                missingCount++;
            }
        }

        // Create properly sized result array
        missing = new string[](missingCount);
        for (uint256 i = 0; i < missingCount; i++) {
            missing[i] = tempMissing[i];
        }

        return (missingCount == 0, missing);
    }
}

// Example 3: Build mapping of module implementations
function getAllModuleImplementations(
    address beaconAddress
) external view returns (
    string[] memory moduleNames,
    address[] memory implementations
) {
    IBeacon beacon = IBeacon(beaconAddress);
    moduleNames = beacon.getRegisteredModules();
    implementations = new address[](moduleNames.length);

    for (uint256 i = 0; i < moduleNames.length; i++) {
        // Note: This will revert if module is frozen
        // In production, wrap in try-catch
        implementations[i] = beacon.getImplementation(moduleNames[i]);
    }

    return (moduleNames, implementations);
}

