// Example 5: Search for specific module
function findModule(
    address beaconAddress,
    string memory targetModule
) external view returns (bool found, uint256 index) {
    IBeacon beacon = IBeacon(beaconAddress);
    string[] memory modules = beacon.getRegisteredModules();

    for (uint256 i = 0; i < modules.length; i++) {
        if (keccak256(bytes(modules[i])) == keccak256(bytes(targetModule))) {
            return (true, i);
        }
    }

    return (false, 0);
}

