// Example 2: Rollback to previous version
contract UpgradeRollback {
    IBeacon public beacon;

    function rollbackToPreviousVersion(string memory moduleName) 
        external 
        onlyOwner 
    {
        address[] memory history = beacon.getImplementationHistory(moduleName);
        require(history.length > 0, "No previous versions available");

        // Get most recent previous implementation (last in array)
        address previousImpl = history[history.length - 1];

        // Rollback by updating to previous version
        // Note: This adds current bad version to history
        beacon.updateImplementation(moduleName, previousImpl);

        emit RolledBack(moduleName, previousImpl);
    }

    function rollbackToSpecificVersion(
        string memory moduleName,
        uint256 versionIndex
    ) external onlyOwner {
        address[] memory history = beacon.getImplementationHistory(moduleName);
        require(versionIndex < history.length, "Version index out of bounds");

        address targetImpl = history[versionIndex];
        beacon.updateImplementation(moduleName, targetImpl);

        emit RolledBackToVersion(moduleName, targetImpl, versionIndex);
    }
}

// Example 3: Audit trail analysis
function analyzeUpgradePattern(
    address beaconAddress,
    string memory moduleName
) external view returns (
    uint256 totalUpgrades,
    uint256 daysSinceFirstVersion,
    address firstImplementation,
    address currentImplementation
) {
    IBeacon beacon = IBeacon(beaconAddress);

    address[] memory history = beacon.getImplementationHistory(moduleName);
    totalUpgrades = history.length;

    (
        address current,
        uint256 lastUpdated,
        ,
    ) = beacon.getModuleInfo(moduleName);

    currentImplementation = current;

    if (history.length > 0) {
        firstImplementation = history[0];
        // Calculate time since first upgrade
        daysSinceFirstVersion = (block.timestamp - lastUpdated) / 1 days;
    }

    return (totalUpgrades, daysSinceFirstVersion, firstImplementation, currentImplementation);
}

// Example 4: Version compatibility checker
contract VersionChecker {
    // Known compatible implementation addresses
    mapping(address => bool) public knownSafeVersions;

    function isCurrentVersionSafe(
        address beaconAddress,
        string memory moduleName
    ) external view returns (bool isSafe, string memory reason) {
        IBeacon beacon = IBeacon(beaconAddress);

        try beacon.getImplementation(moduleName) returns (address current) {
            if (knownSafeVersions[current]) {
                return (true, "Current version is in safe list");
            }

            // Check if any previous version was safe
            address[] memory history = beacon.getImplementationHistory(moduleName);
            for (uint256 i = 0; i < history.length; i++) {
                if (knownSafeVersions[history[i]]) {
                    return (false, "Current version not in safe list, but previous versions were");
                }
            }

            return (false, "No safe versions found in history");
        } catch {
            return (false, "Module frozen or not registered");
        }
    }
}

// Example 5: Generate upgrade report
function generateUpgradeReport(
    address beaconAddress,
    string memory moduleName
) external view returns (
    address[] memory allVersions,
    uint256[] memory timestamps,
    bool[] memory isCurrentlyDeployed
) {
    IBeacon beacon = IBeacon(beaconAddress);

    address[] memory history = beacon.getImplementationHistory(moduleName);
    address current = beacon.getImplementation(moduleName);

    // Include current version in report
    uint256 totalVersions = history.length + 1;
    allVersions = new address[](totalVersions);
    isCurrentlyDeployed = new bool[](totalVersions);

    // Copy historical versions
    for (uint256 i = 0; i < history.length; i++) {
        allVersions[i] = history[i];
        isCurrentlyDeployed[i] = false;
    }

    // Add current version
    allVersions[totalVersions - 1] = current;
    isCurrentlyDeployed[totalVersions - 1] = true;

    return (allVersions, timestamps, isCurrentlyDeployed);
}

