// Example 2: Validate module before using
function safeModuleAccess(string memory moduleName) internal view returns (address implementation) {
    (
        address impl,
        uint256 lastUpd,
        ,
        bool frozen
    ) = beacon.getModuleInfo(moduleName);

    require(impl != address(0), "Module not registered");
    require(!frozen, "Module is frozen");
    require(lastUpd > 0, "Module never initialized");

    // Additional staleness check - warn if > 180 days old
    if (block.timestamp - lastUpd > 180 days) {
        emit StaleModuleWarning(moduleName, lastUpd);
    }

