// Example 4: Module maturity scoring
function calculateModuleMaturity(
    address beaconAddress,
    string memory moduleName
) external view returns (uint256 maturityScore, string memory rating) {
    IBeacon beacon = IBeacon(beaconAddress);
    (
        address impl,
        uint256 lastUpd,
        uint256 histCount,
    ) = beacon.getModuleInfo(moduleName);

    require(impl != address(0), "Module not registered");

    // Scoring factors:
    // - Time since first deployment (older = more mature)
    // - Number of upgrades (some upgrades show maintenance, too many shows instability)
    // - Stability (time since last update)

    uint256 ageScore = (block.timestamp - lastUpd) / 30 days; // Months old
    uint256 upgradeScore = histCount >= 2 && histCount <= 10 ? 50 : 0; // Sweet spot
    uint256 stabilityScore = (block.timestamp - lastUpd) > 90 days ? 30 : 0;

    maturityScore = ageScore + upgradeScore + stabilityScore;

    if (maturityScore >= 100) rating = "Mature";
    else if (maturityScore >= 50) rating = "Developing";
    else rating = "Experimental";

    return (maturityScore, rating);
}

// Example 5: Emergency response workflow
contract EmergencyCoordinator {
    IBeacon public beacon;

    function assessEmergencyImpact(
        string memory affectedModule
    ) external view returns (
        bool canFreeze,
        bool alreadyFrozen,
        uint256 timeSinceLastChange,
        address rollbackTarget
    ) {
        (
            address current,
            uint256 lastUpd,
            uint256 histCount,
            bool frozen
        ) = beacon.getModuleInfo(affectedModule);

        canFreeze = current != address(0); // Can only freeze registered modules
        alreadyFrozen = frozen;
        timeSinceLastChange = block.timestamp - lastUpd;

        // Suggest rollback target if recent upgrade might be problematic
        if (histCount > 0 && timeSinceLastChange < 7 days) {
            address[] memory history = beacon.getImplementationHistory(affectedModule);
            rollbackTarget = history[history.length - 1]; // Most recent previous version
        }

        return (canFreeze, alreadyFrozen, timeSinceLastChange, rollbackTarget);
    }
}

