// Example 3: Selective freeze based on health check
function freezeUnhealthyModules(
    address beaconAddress
) external onlyRole(GUARDIAN_ROLE) {
    IBeacon beacon = IBeacon(beaconAddress);
    string[] memory modules = beacon.getRegisteredModules();

    for (uint256 i = 0; i < modules.length; i++) {
        // Check module health (custom logic)
        if (isModuleUnhealthy(modules[i])) {
            try beacon.freezeModule(modules[i]) {
                emit ModuleFrozenForHealth(modules[i]);
            } catch {
                // Module might already be frozen or other issue
                emit FreezeFailed(modules[i]);
            }
