// Example 4: Coordinated multi-module response
contract IncidentCoordinator {
    IBeacon public beacon;
    mapping(string => string[]) public dependentModules;

    // If TokenManager has issues, freeze dependent modules too
    function freezeWithDependents(string memory primaryModule) external onlyOwner {
        // Freeze primary module
        beacon.freezeModule(primaryModule);
        emit PrimaryModuleFrozen(primaryModule);

        // Freeze all dependent modules
        string[] memory deps = dependentModules[primaryModule];
        for (uint256 i = 0; i < deps.length; i++) {
            try beacon.freezeModule(deps[i]) {
                emit DependentModuleFrozen(deps[i], primaryModule);
            } catch {
                // Already frozen or doesn't exist
            }
        }
    }
}

// Example 5: Time-delayed freeze (governance)
contract GovernanceFreeze {
    IBeacon public beacon;

    struct FreezeProposal {
        string moduleName;
        uint256 proposalTime;
        uint256 executionTime;
        bool executed;
        string reason;
    }

    mapping(uint256 => FreezeProposal) public proposals;
    uint256 public proposalCount;
    uint256 public constant TIMELOCK = 24 hours;

    function proposeFr eze(
        string memory moduleName,
        string memory reason
    ) external onlyGovernance returns (uint256 proposalId) {
        proposalId = proposalCount++;
        proposals[proposalId] = FreezeProposal({
            moduleName: moduleName,
            proposalTime: block.timestamp,
            executionTime: block.timestamp + TIMELOCK,
            executed: false,
            reason: reason
        });

        emit FreezePro posed(proposalId, moduleName, reason);
    }

    function executeFreeze(uint256 proposalId) external {
        FreezeProposal storage prop = proposals[proposalId];
        require(!prop.executed, "Already executed");
        require(block.timestamp >= prop.executionTime, "Timelock not expired");

        beacon.freezeModule(prop.moduleName);
        prop.executed = true;

        emit FreezeExecuted(proposalId, prop.moduleName);
    }
}

