// ============================================
// EXAMPLE 1: Basic Incident Resolution
// ============================================
// Context: SwapManager was frozen 2 hours ago due to
// suspicious oracle price anomaly. Investigation revealed
// it was a false alarm (temporary Chainlink network congestion).
// Now restoring service:

IBeacon beacon = IBeacon(BEACON_ADDRESS);

// Verify module is currently frozen
(, , , bool isFrozen) = beacon.getModuleInfo("SwapManager");
require(isFrozen, "Module not frozen");

// Restore module access
beacon.unfreezeModule("SwapManager");
// ✅ ModuleUnfrozen("SwapManager", msg.sender) emitted
// ✅ All proxy contracts can now resume swap operations
// ✅ getImplementation("SwapManager") returns valid address

// ============================================
// EXAMPLE 2: Coordinated Multi-Module Recovery
// ============================================
// Context: Multiple modules were frozen during a system-wide
// security audit. Modules are being restored incrementally
// as they pass verification checks.

contract IncidentRecoveryCoordinator {
    IBeacon public beacon;
    mapping(string => bool) public verifiedSafe;

    function restoreModule(string memory module) external onlyIncidentCommander {
        // Check module passed security verification
        require(verifiedSafe[module], "Module not cleared for restoration");

        // Verify module is registered and frozen
        (address impl, , , bool frozen) = beacon.getModuleInfo(module);
        require(impl != address(0), "Module not registered");
        require(frozen, "Module not frozen");

        // Restore module (requires this coordinator to be Beacon owner)
        beacon.unfreezeModule(module);

        // Log recovery action
        emit ModuleRestored(module, block.timestamp);
    }

    function batchRestore(string[] memory modules) external onlyIncidentCommander {
        for (uint i = 0; i < modules.length; i++) {
            // Only restore modules that are actually frozen
            (, , , bool frozen) = beacon.getModuleInfo(modules[i]);
            if (frozen && verifiedSafe[modules[i]]) {
                beacon.unfreezeModule(modules[i]);
            }
        }
    }
}

// ============================================
// EXAMPLE 3: Post-Upgrade Verification Unfreeze
// ============================================
// Context: Module was frozen before upgrade, implementation
// was updated while frozen, now verifying and restoring.

// Step 1: Freeze module for safe upgrade
beacon.freezeModule("TokenManager");

// Step 2: Deploy new implementation and update
address newImpl = address(new TokenManagerV2());
beacon.updateImplementation("TokenManager", newImpl);

// Step 3: Run smoke tests on frozen module
// (proxies cannot access it yet, so test directly)
TokenManagerV2 testInstance = TokenManagerV2(newImpl);
require(testInstance.version() == 2, "Version check failed");
testInstance.depositToken{value: 0.1 ether}(address(0), 0.1 ether);
// ... additional tests ...

// Step 4: Tests passed, restore module access
beacon.unfreezeModule("TokenManager");
// ✅ All proxies now route to new V2 implementation
// ✅ Zero downtime for end users (upgrade was atomic)

// ============================================
// EXAMPLE 4: Time-Delayed Unfreeze with Governance
// ============================================
// Context: Governance system requires 24h timelock before
// unfreezing critical modules after security incidents.

contract GovernedBeaconOperator {
    IBeacon public beacon;
    mapping(string => uint256) public unfreezeTimestamp;
    uint256 public constant UNFREEZE_DELAY = 24 hours;

    function scheduleUnfreeze(string memory module) external onlyGovernance {
        // Verify module is frozen
        (, , , bool frozen) = beacon.getModuleInfo(module);
        require(frozen, "Module not frozen");

        // Schedule unfreeze for 24h from now
        unfreezeTimestamp[module] = block.timestamp + UNFREEZE_DELAY;
        emit UnfreezeScheduled(module, unfreezeTimestamp[module]);
    }

    function executeUnfreeze(string memory module) external {
        // Check timelock has elapsed
        require(unfreezeTimestamp[module] != 0, "Unfreeze not scheduled");
        require(block.timestamp >= unfreezeTimestamp[module], "Timelock active");

        // Execute unfreeze
        beacon.unfreezeModule(module);

        // Clear schedule
        delete unfreezeTimestamp[module];
        emit UnfreezeExecuted(module, block.timestamp);
    }

    function cancelScheduledUnfreeze(string memory module) external onlyGovernance {
        require(unfreezeTimestamp[module] != 0, "No scheduled unfreeze");
        delete unfreezeTimestamp[module];
        emit UnfreezeCancelled(module);
    }
}

// ============================================
// EXAMPLE 5: Emergency Drill - Freeze/Unfreeze Cycle
// ============================================
// Context: Monthly emergency response drill to verify
// freeze/unfreeze mechanisms work correctly under pressure.

contract EmergencyDrillExecutor {
    IBeacon public beacon;

    function executeDrill(string memory testModule) external onlyDrillCoordinator {
        // Record initial state
        (address impl, , , bool initiallyFrozen) = beacon.getModuleInfo(testModule);
        require(impl != address(0), "Invalid test module");

        uint256 gasStart = gasleft();

        // TEST 1: Freeze operation
        if (!initiallyFrozen) {
            beacon.freezeModule(testModule);
            uint256 freezeGas = gasStart - gasleft();
            emit DrillResult("freeze", testModule, freezeGas, true);
        }

        // Verify frozen state
        (, , , bool frozen) = beacon.getModuleInfo(testModule);
        require(frozen, "Freeze verification failed");

        // TEST 2: Verify implementation lookup fails
        try beacon.getImplementation(testModule) returns (address) {
            emit DrillResult("freeze_validation", testModule, 0, false);
            revert("Frozen module should not return implementation");
        } catch {
            emit DrillResult("freeze_validation", testModule, 0, true);
        }

        gasStart = gasleft();

        // TEST 3: Unfreeze operation
        beacon.unfreezeModule(testModule);
        uint256 unfreezeGas = gasStart - gasleft();
        emit DrillResult("unfreeze", testModule, unfreezeGas, true);

        // TEST 4: Verify implementation lookup succeeds
        address restoredImpl = beacon.getImplementation(testModule);
        require(restoredImpl == impl, "Implementation mismatch after unfreeze");
        emit DrillResult("unfreeze_validation", testModule, 0, true);

        emit DrillCompleted(testModule, block.timestamp);
    }
}

