// ============================================
// EXAMPLE 1: Post-Incident Service Restoration
// ============================================
// Context: Global freeze was activated 6 hours ago due to
// critical Beacon vulnerability. Fix has been deployed,
// tested, and verified. Ready to restore service.

IBeacon beacon = IBeacon(BEACON_ADDRESS);

// PRE-RESTORATION CHECKLIST (manual verification):
// ✅ Security vulnerability patched and deployed
// ✅ All modules tested individually (direct calls)
// ✅ Smoke tests passed on testnet with same configuration
// ✅ Incident post-mortem completed
// ✅ Public communication drafted and ready
// ✅ Monitoring alerts configured for anomaly detection
// ✅ Operations team on standby for post-restoration monitoring
// ✅ Rollback plan documented if issues arise

// Verify global freeze is currently active
require(beacon.globalFreeze(), "Already operational");

// RESTORE SERVICE
beacon.deactivateGlobalFreeze();
// ✅ GlobalFreezeDeactivated(msg.sender) emitted
// ✅ All module implementation lookups now succeed
// ✅ All proxy contracts can route to implementations
// ✅ Users can resume normal protocol interactions

// POST-RESTORATION MONITORING (next 24 hours):
// - Monitor error rates for anomalies
// - Track gas consumption for unexpected changes
// - Watch for suspicious transaction patterns
// - Verify TVL stabilizes and recovers
// - Check user feedback and support tickets

// ============================================
// EXAMPLE 2: Governance-Approved Restoration
// ============================================
// Context: Global freeze was activated during security audit.
// Governance vote has approved restoration after audit clearance.

contract GovernanceExecutor {
    IBeacon public beacon;

    function executeRestoration(uint256 proposalId) external {
        Proposal memory proposal = proposals[proposalId];

        // Verify governance requirements met
        require(proposal.proposalType == ProposalType.DeactivateGlobalFreeze, "Wrong proposal type");
        require(proposal.votesPassed, "Proposal did not pass");
        require(block.timestamp >= proposal.timelockExpiry, "Timelock active");
        require(!proposal.executed, "Already executed");

        // Additional safety checks
        require(proposal.securityAuditCompleted, "Audit not completed");
        require(proposal.allModulesVerified, "Module verification incomplete");

        // Execute restoration with governance approval
        beacon.deactivateGlobalFreeze();

        proposal.executed = true;
        emit GovernanceRestorationExecuted(
            proposalId,
            msg.sender,
            block.timestamp
        );

        // Trigger post-restoration monitoring
        _activateEnhancedMonitoring(24 hours);
    }
}

// ============================================
// EXAMPLE 3: Coordinated Multi-System Restoration
// ============================================
// Context: Protocol freeze required coordinated pausing of
// multiple external integrations. Restoration must be orchestrated.

contract RestorationCoordinator {
    IBeacon public beacon;
    address[] public dependentSystems;
    mapping(address => bool) public systemReady;

    function signalSystemReady(address system) external onlySystemOperator(system) {
        systemReady[system] = true;
        emit SystemReadySignaled(system, block.timestamp);
    }

    function executeCoordinatedRestoration() external onlyEmergencyCoordinator {
        // Verify ALL dependent systems are ready
        for (uint i = 0; i < dependentSystems.length; i++) {
            require(
                systemReady[dependentSystems[i]],
                string(abi.encodePacked("System not ready: ", dependentSystems[i]))
            );
        }

        // Verify Beacon modules are healthy
        require(_allModulesHealthy(), "Module health check failed");

        // PHASE 1: Restore Beacon (enables lookups)
        beacon.deactivateGlobalFreeze();
        emit BeaconRestored(block.timestamp);

        // PHASE 2: Signal dependent systems to resume (off-chain webhooks)
        _notifyDependentSystems("RESUME_OPERATIONS");

        // PHASE 3: Gradually increase rate limits (prevent surge)
        _setRateLimit(10); // Start at 10 tx/min
        emit GradualRolloutInitiated();
    }

    function _allModulesHealthy() internal view returns (bool) {
        string[] memory modules = beacon.getRegisteredModules();
        for (uint i = 0; i < modules.length; i++) {
            address impl = beacon.getImplementation(modules[i]);
            if (impl == address(0) || impl.code.length == 0) {
                return false;
            }
        }
        return true;
    }
}

// ============================================
// EXAMPLE 4: Staged Restoration with Canary Users
// ============================================
// Context: After major incident, restore service gradually
// starting with small user subset before full rollout.

contract CanaryRestoration {
    IBeacon public beacon;
    mapping(address => bool) public canaryUsers;
    bool public fullRollout;

    function restoreForCanaryUsers() external onlyOwner {
        // Deactivate global freeze (allows lookups)
        beacon.deactivateGlobalFreeze();

        // But maintain access control at proxy level
        // (requires custom proxy implementation)
        fullRollout = false;
        emit CanaryPhaseStarted(block.timestamp);
    }

    function promoteToFullRollout() external onlyOwner {
        require(!fullRollout, "Already full rollout");

        // After canary period (e.g., 24 hours) with no issues,
        // open access to all users
        fullRollout = true;
        emit FullRolloutActivated(block.timestamp);
    }
}

// ============================================
// EXAMPLE 5: Automated Post-Restoration Health Monitoring
// ============================================
// Context: After restoration, automatically monitor system
// health and re-freeze if anomalies detected.

contract PostRestorationMonitor {
    IBeacon public beacon;
    uint256 public restorationTime;
    uint256 public constant CRITICAL_MONITORING_PERIOD = 1 hours;

    // Anomaly detection thresholds
    uint256 public maxErrorRatePercent = 5; // 5% error rate triggers re-freeze
    uint256 public maxGasDeviationPercent = 50; // 50% gas increase triggers alert

    function onRestorationDetected() external {
        // Called by event listener when GlobalFreezeDeactivated detected
        restorationTime = block.timestamp;
        emit EnhancedMonitoringActivated(CRITICAL_MONITORING_PERIOD);
    }

    function checkPostRestorationHealth() external {
        require(
            block.timestamp < restorationTime + CRITICAL_MONITORING_PERIOD,
            "Monitoring period expired"
        );

        // Check error rates
        uint256 errorRate = _calculateRecentErrorRate();
        if (errorRate > maxErrorRatePercent) {
            // AUTOMATIC RE-FREEZE: Abnormal error rate detected
            beacon.activateGlobalFreeze();
            emit AutomaticReFreeze(
                "High error rate detected",
                errorRate,
                block.timestamp
            );
            return;
        }

        // Check gas consumption patterns
        uint256 gasDeviation = _calculateGasDeviation();
        if (gasDeviation > maxGasDeviationPercent) {
            // Possible attack or malicious code injection
            beacon.activateGlobalFreeze();
            emit AutomaticReFreeze(
                "Abnormal gas consumption",
                gasDeviation,
                block.timestamp
            );
            return;
        }

        emit HealthCheckPassed(block.timestamp);
    }
}

