contract SafeOwnershipTransfer {
    IBeacon public beacon;

    function transferWithVerification(
        address newOwner
    ) external onlyCurrentOwner {
        // VERIFICATION STEP 1: Check new owner is contract with acceptOwnership()
        if (newOwner.code.length > 0) {
            // It's a contract - verify it has acceptOwnership function
            try IBeacon(newOwner).acceptOwnership() {
                // Would succeed but we're just testing selector
                revert("Dry run successful - proceed with actual transfer");
            } catch {
                revert("New owner contract cannot accept ownership");
            }
