// ============================================
// EXAMPLE 5: Time-Limited Transfer Proposal
// ============================================
// Context: Transfer proposal should expire if not accepted
// within reasonable timeframe (prevent stale proposals).

contract TimeLimitedOwnershipTransfer {
    IBeacon public beacon;
    mapping(address => uint256) public transferProposalTimestamp;
    uint256 public constant PROPOSAL_EXPIRY = 7 days;

    function proposeOwnershipTransfer(
        address newOwner
    ) external onlyCurrentOwner {
        // Cancel any existing pending transfer first
        if (beacon.pendingOwner() != address(0)) {
            beacon.cancelOwnershipTransfer();
        }

        // Initiate new transfer
        beacon.transferOwnership(newOwner);

        // Record proposal timestamp
        transferProposalTimestamp[newOwner] = block.timestamp;

        emit OwnershipTransferProposed(
            newOwner,
            block.timestamp,
            block.timestamp + PROPOSAL_EXPIRY
        );
    }

    function cancelExpiredProposal() external {
        address pending = beacon.pendingOwner();
        require(pending != address(0), "No pending transfer");

        uint256 proposalTime = transferProposalTimestamp[pending];
        require(
            block.timestamp >= proposalTime + PROPOSAL_EXPIRY,
            "Proposal not expired"
        );

        // Cancel expired proposal
        beacon.cancelOwnershipTransfer();
        delete transferProposalTimestamp[pending];

        emit ExpiredProposalCancelled(pending, block.timestamp);
    }
}

// ============================================
// EXAMPLE 6: Multi-Stage Governance Transition
// ============================================
// Context: Complex handoff requiring multiple approval stages.

contract MultiStageGovernanceTransition {
    IBeacon public beacon;

    enum Stage { Proposed, Approved, Initiated, Completed }

    struct Transition {
        address proposedOwner;
        uint256 proposalTime;
        uint256 approvalCount;
        Stage stage;
    }

    Transition public currentTransition;
    mapping(address => bool) public hasApproved;
    uint256 public constant REQUIRED_APPROVALS = 3;

    function proposeTransition(address newOwner) external onlyCouncil {
        require(
            currentTransition.stage == Stage.Completed || currentTransition.stage == Stage(0),
            "Transition in progress"
        );

        currentTransition = Transition({
            proposedOwner: newOwner,
            proposalTime: block.timestamp,
            approvalCount: 1,
            stage: Stage.Proposed
        });

        hasApproved[msg.sender] = true;
        emit TransitionProposed(newOwner, block.timestamp);
    }

    function approveTransition() external onlyCouncil {
        require(
            currentTransition.stage == Stage.Proposed,
            "Wrong stage"
        );
        require(!hasApproved[msg.sender], "Already approved");

        hasApproved[msg.sender] = true;
        currentTransition.approvalCount++;

        if (currentTransition.approvalCount >= REQUIRED_APPROVALS) {
            currentTransition.stage = Stage.Approved;
            emit TransitionApproved(currentTransition.proposedOwner);
        }
    }

    function executeTransition() external onlyCurrentOwner {
        require(
            currentTransition.stage == Stage.Approved,
            "Not approved"
        );

        // Initiate actual ownership transfer
        beacon.transferOwnership(currentTransition.proposedOwner);

        currentTransition.stage = Stage.Initiated;
        emit TransitionInitiated(currentTransition.proposedOwner);
    }
}

