// ============================================
// EXAMPLE 4: Acceptance with Pre-Flight Checks
// ============================================
// Context: New owner wants to verify system state before
// accepting to ensure no surprises.

contract SafeOwnershipAcceptance {
    IBeacon public beacon;

    function acceptWithVerification() external {
        // Verify we are the pending owner
        require(
            beacon.pendingOwner() == address(this),
            "Not pending owner"
        );

        // PRE-ACCEPTANCE CHECKS
        // Check 1: Verify no modules are frozen
        string[] memory modules = beacon.getRegisteredModules();
        for (uint i = 0; i < modules.length; i++) {
            (, , , bool frozen) = beacon.getModuleInfo(modules[i]);
            require(!frozen, string(abi.encodePacked("Module frozen: ", modules[i])));
        }

        // Check 2: Verify no global freeze active
        require(!beacon.globalFreeze(), "Global freeze active");

        // Check 3: Verify all implementations are valid contracts
        for (uint i = 0; i < modules.length; i++) {
            address impl = beacon.getImplementation(modules[i]);
            require(impl != address(0), "Zero implementation");
            require(impl.code.length > 0, "Not a contract");
        }

        // Check 4: Verify no unexpected pending ownership changes
        // (current owner hasn't initiated another transfer)
        require(
            beacon.pendingOwner() == address(this),
            "Pending owner changed during checks"
        );

        // All checks passed - accept ownership
        beacon.acceptOwnership();

        emit SafeOwnershipAccepted(
            address(this),
            modules.length,
            block.timestamp
        );
    }
}

// ============================================
// EXAMPLE 5: Conditional Acceptance via Governance
// ============================================
// Context: New owner (DAO) requires community approval
// before accepting ownership.

contract ConditionalAcceptance {
    IBeacon public beacon;

    struct AcceptanceProposal {
        uint256 proposalId;
        uint256 proposedAt;
        uint256 votesFor;
        uint256 votesAgainst;
        bool executed;
    }

    AcceptanceProposal public currentProposal;
    mapping(address => bool) public hasVoted;

    uint256 public constant VOTING_PERIOD = 3 days;
    uint256 public constant QUORUM = 1000000e18; // 1M tokens

    function proposeAcceptance() external {
        require(
            beacon.pendingOwner() == address(this),
            "Not pending owner"
        );
        require(
            currentProposal.proposalId == 0 || currentProposal.executed,
            "Active proposal exists"
        );

        currentProposal = AcceptanceProposal({
            proposalId: block.number,
            proposedAt: block.timestamp,
            votesFor: 0,
            votesAgainst: 0,
            executed: false
        });

        emit AcceptanceProposed(block.number, block.timestamp);
    }

    function vote(bool support) external {
        require(
            block.timestamp < currentProposal.proposedAt + VOTING_PERIOD,
            "Voting ended"
        );
        require(!hasVoted[msg.sender], "Already voted");

        uint256 votingPower = _getVotingPower(msg.sender);

        if (support) {
            currentProposal.votesFor += votingPower;
        } else {
            currentProposal.votesAgainst += votingPower;
        }

        hasVoted[msg.sender] = true;
        emit Voted(msg.sender, support, votingPower);
    }

    function executeAcceptance() external {
        require(
            block.timestamp >= currentProposal.proposedAt + VOTING_PERIOD,
            "Voting period active"
        );
        require(!currentProposal.executed, "Already executed");
        require(
            currentProposal.votesFor > currentProposal.votesAgainst,
            "Proposal rejected"
        );
        require(
            currentProposal.votesFor >= QUORUM,
            "Quorum not reached"
        );

        // Community approved - accept ownership
        beacon.acceptOwnership();

        currentProposal.executed = true;
        emit AcceptanceExecuted(block.timestamp);
    }
}

// ============================================
// EXAMPLE 6: Acceptance with Immediate Actions
// ============================================
// Context: New owner accepts and immediately executes
// critical governance actions.

contract AcceptAndAct {
    IBeacon public beacon;

    function acceptAndFreeze() external onlyAuthorizedAcceptor {
        // Accept ownership
        beacon.acceptOwnership();
        // ✅ We are now owner

        // Immediately freeze suspicious module
        beacon.freezeModule("SwapManager");

        emit OwnershipAcceptedAndActionTaken(
            "SwapManager frozen",
            block.timestamp
        );
    }

    function acceptAndUpgrade(
        string memory module,
        address newImpl
    ) external onlyAuthorizedAcceptor {
        // Accept ownership
        beacon.acceptOwnership();
        // ✅ We are now owner

        // Immediately deploy critical upgrade
        beacon.updateImplementation(module, newImpl);

        emit OwnershipAcceptedAndActionTaken(
            "Implementation upgraded",
            block.timestamp
        );
    }
}

beacon-cancelownershiptransfer.usageExample:
// ============================================
// EXAMPLE 1: Correcting Address Typo
// ============================================
// Context: Owner initiated transfer to wrong address due
// to copy-paste error. Catch before acceptance.

IBeacon beacon = IBeacon(BEACON_ADDRESS);

// WRONG: Accidentally transferred to typo address
address wrongAddress = 0x1234567890123456789012345678901234567890;
beacon.transferOwnership(wrongAddress);
// ✅ OwnershipTransferInitiated(owner, wrongAddress)

// Immediately realize mistake before wrongAddress notices
// CANCEL the bad transfer
beacon.cancelOwnershipTransfer();
// ✅ pendingOwner cleared to address(0)
// ⚠️ No event emitted (pending owner not notified on-chain)

// Initiate correct transfer
address correctAddress = 0x1234567890123456789012345678901234567891; // Fixed typo
beacon.transferOwnership(correctAddress);
// ✅ OwnershipTransferInitiated(owner, correctAddress)
// ✅ Correct address can now accept

// ============================================
// EXAMPLE 2: Responding to Unresponsive Pending Owner
// ============================================
// Context: Transfer initiated to multisig but signers
// are unresponsive for weeks. Need to move forward.

contract OwnershipCoordinator {
    IBeacon public beacon;
    uint256 public transferInitiatedAt;
    uint256 public constant ACCEPTANCE_TIMEOUT = 30 days;

    function initiateTransfer(address newOwner) external onlyCurrentOwner {
        beacon.transferOwnership(newOwner);
        transferInitiatedAt = block.timestamp;
        emit TransferInitiated(newOwner, block.timestamp);
    }

    function cancelStaleTransfer() external onlyCurrentOwner {
        require(
            beacon.pendingOwner() != address(0),
            "No pending transfer"
        );
        require(
            block.timestamp >= transferInitiatedAt + ACCEPTANCE_TIMEOUT,
            "Timeout not reached"
        );

        // Pending owner didn't accept within 30 days - cancel
        address stalePendingOwner = beacon.pendingOwner();
        beacon.cancelOwnershipTransfer();

        emit StaleTransferCancelled(
            stalePendingOwner,
            block.timestamp - transferInitiatedAt
        );

        // Can now initiate fresh transfer to backup address
    }
}

// ============================================
// EXAMPLE 3: Emergency Cancellation on Compromise Suspicion
// ============================================
// Context: Pending owner's address activity looks suspicious.
// Cancel before they can accept.

contract EmergencyCancellation {
    IBeacon public beacon;
    address public securityCoordinator;

    function emergencyCancel(string memory reason) external {
        require(
            msg.sender == securityCoordinator,
            "Not authorized"
        );
        require(
            beacon.pendingOwner() != address(0),
            "No pending transfer"
        );

        // Security team detected suspicious activity
        // Cancel transfer immediately
        address suspiciousPendingOwner = beacon.pendingOwner();
        beacon.cancelOwnershipTransfer();

        emit EmergencyCancellation(
            suspiciousPendingOwner,
            reason,
            block.timestamp
        );

        // Begin investigation of suspicious address
        _investigateAddress(suspiciousPendingOwner);
    }
}

// ============================================
// EXAMPLE 4: Changed Circumstances
// ============================================
// Context: Governance vote fails after transfer initiated,
// community rejects proposed new owner.

contract GovernanceVotedCancellation {
    IBeacon public beacon;

    struct CancellationProposal {
        uint256 proposalId;
        address pendingOwnerToCancel;
        uint256 votesFor;
        uint256 votesAgainst;
        bool executed;
    }

    CancellationProposal public currentProposal;

    function proposeTransferCancellation() external {
        address pending = beacon.pendingOwner();
        require(pending != address(0), "No pending transfer");

        currentProposal = CancellationProposal({
            proposalId: block.number,
            pendingOwnerToCancel: pending,
            votesFor: 0,
            votesAgainst: 0,
            executed: false
        });

        emit CancellationProposed(pending, block.number);
    }

    function executeCancellation() external onlyCurrentOwner {
        require(!currentProposal.executed, "Already executed");
        require(
            currentProposal.votesFor > currentProposal.votesAgainst,
            "Vote did not pass"
        );

        // Community voted to cancel - execute
        beacon.cancelOwnershipTransfer();

        currentProposal.executed = true;
        emit CancellationExecuted(
            currentProposal.pendingOwnerToCancel,
            block.timestamp
        );
    }
}

// ============================================
// EXAMPLE 5: Preventing Front-Running Attack
// ============================================
// Context: Malicious current owner tries to cancel right
// before pending owner's acceptance transaction confirms.

// This scenario demonstrates the front-running risk:

// 1. Current owner (malicious) initiates transfer
beacon.transferOwnership(legitimatePendingOwner);

// 2. Legitimate pending owner prepares acceptance
// (spends days coordinating multisig signatures)

// 3. Pending owner submits acceptOwnership() to mempool

// 4. Malicious current owner sees pending tx in mempool
// and front-runs with higher gas:
beacon.cancelOwnershipTransfer(); // ← Confirms BEFORE acceptance

// 5. Pending owner's acceptance tx now fails:
// acceptOwnership() reverts because pendingOwner was cleared

// MITIGATION: Use private mempool (Flashbots)
flashbotsRelay.sendPrivateTransaction(acceptOwnershipTx);

// ============================================
// EXAMPLE 6: Cancelling to Re-Initiate Different Address
// ============================================
// Context: Owner decides to transfer to different address
// than originally proposed.

contract TransferRedirection {
    IBeacon public beacon;

    function redirectTransfer(
        address newPendingOwner
    ) external onlyCurrentOwner {
        // Check if there's an existing pending transfer
        if (beacon.pendingOwner() != address(0)) {
            // Cancel existing transfer
            address oldPending = beacon.pendingOwner();
            beacon.cancelOwnershipTransfer();

            emit TransferRedirected(
                oldPending,
                newPendingOwner,
                block.timestamp
            );
        }

        // Initiate transfer to new address
        beacon.transferOwnership(newPendingOwner);
    }
}

