modules[0] = "NewModule";
modules[1] = "SwapManager";
address[] memory newImpls = new address[](2);
newImpls[0] = 0xNEW_MODULE_IMPL;
newImpls[1] = 0xNEW_SWAP_MANAGER;
beacon.batchUpdateImplementations(modules, newImpls);

